          "ja": "モーセ書 1:24-35",
          "en": "Moses 1:24-35",
          "ko": "Moses 1:24-35",
          "zho": "モーセ書 1:24-35",
          "es": "Moses 1:24-35",
          "pt": "Moses 1:24-35",
