        comment: {
          "ja": "すべての武具を溶かして農具にするというビジョンは、人間の外交政策を遥かに超えた究極の平和への壮大な遠回りです。",
          "en": "Beating swords into plowshares is the ultimate divine downscaling of military budgets into something that actually feeds us.",
          "ko": "칼을 쳐서 보습을 만드는 것은 인간의 외교적 계산을 뛰어넘는 가장 현실적이고 웅장한 평화의 구상입니다.",
          "zho": "把刀劍打成犁頭，是超越人類外交辭令的終極和平藍圖。",
          "es": "Forjar espadas en rejas de arado es la desmilitarización divina más audaz concebida para alimentar en lugar de destruir.",
          "pt": "Transformar espadas em relhas de arado é o redesenho divino mais radical de orçamento militar para a sobrevivência humana.",
          "vi": "Biến gươm giáo thành cuốc cày là tầm nhìn hòa bình vĩ đại vượt qua mọi toan tính ngoại giao nhân loại.",
          "tl": "Ang paggawa ng mga tabak bilang mga sudsod ay ang pinakadakilang pananaw ng kapayapaan na lumalampas sa pulitika.",
          "th": "การตีดาบเป็นผาลไถคือวิสัยทัศน์แห่งสันติภาพอันยิ่งใหญ่ที่เหนือกว่าการทูตใด ๆ ของมนุษย์",
          "sw": "Kupiga panga kuwa majembe ni maono makuu ya amani yanayopita mipaka ya siasa za kibinadamu.",
          "it": "Trasformare le spade in vomeri è la visione di pace più audace e radicale che trascende ogni diplomazia umana."
        }
