          "ja": "イザヤ書 60:1-22",
          "en": "Isaiah 60:1-22",
          "ko": "Isaiah 60:1-22",
          "zho": "イザヤ書 60:1-22",
          "es": "Isaiah 60:1-22",
          "pt": "Isaiah 60:1-22",
