          "ja": "マラキ書 3:6-18",
          "en": "Malachi 3:6-18",
          "ko": "Malachi 3:6-18",
          "zho": "マラキ書 3:6-18",
          "es": "Malachi 3:6-18",
          "pt": "Malachi 3:6-18",
